{% set conf_current_y = printer.configfile.settings[conf_name].run_current|float %}
SET_TMC_CURRENT STEPPER=stepper_y CURRENT={cut_current_y}

{% if awd %}
SET_TMC_CURRENT STEPPER=stepper_y1 CURRENT={cut_current_y}
