gcode_macro afc_kick.gcode:
{% set gVars              = printer['gcode_macro _AFC_GLOBAL_VARS'] %}
{% set accel              = gVars['accel']            | default(2000)     | float %}
{% set travel_speed       = gVars['travel_speed']     | default(120)*60   | float %}
